//! Centralized path resolution for Bivvy's user-level directories.
//!
//! Uses platform-appropriate directories via the `dirs` crate:
//!
//! | Purpose          | Linux                        | macOS                            | Windows                |
//! |------------------|------------------------------|----------------------------------|------------------------|
//! | Config           | `~/.config/bivvy`            | `~/Library/Application Support/bivvy` | `%APPDATA%/bivvy`     |
//! | Data (state, etc)| `~/.local/share/bivvy`       | `~/Library/Application Support/bivvy` | `%APPDATA%/bivvy`     |
//!
//! The `BIVVY_DATA_DIR` environment variable overrides the data directory,
//! and `BIVVY_CONFIG_DIR` overrides the config directory.

use std::path::PathBuf;

/// Application directory name used under platform config/data dirs.
const APP_DIR_NAME: &str = "bivvy";

/// Returns the user-level config directory for Bivvy.
///
/// Resolution order:
/// 1. `BIVVY_CONFIG_DIR` environment variable (if set)
/// 2. `dirs::config_dir()` / `bivvy` (platform-standard)
/// 3. `~/.bivvy` (legacy fallback)
pub fn config_dir() -> PathBuf {
    if let Ok(dir) = std::env::var("BIVVY_CONFIG_DIR") {
        return PathBuf::from(dir);
    }

    if let Some(dir) = dirs::config_dir() {
        return dir.join(APP_DIR_NAME);
    }

    // Legacy fallback
    dirs::home_dir()
        .unwrap_or_else(|| PathBuf::from("~"))
        .join(".bivvy")
}

/// Returns the user-level data directory for Bivvy.
///
/// Resolution order:
/// 1. `BIVVY_DATA_DIR` environment variable (if set)
/// 2. `dirs::data_dir()` / `bivvy` (platform-standard)
/// 3. `~/.bivvy` (legacy fallback)
pub fn data_dir() -> PathBuf {
    if let Ok(dir) = std::env::var("BIVVY_DATA_DIR") {
        return PathBuf::from(dir);
    }

    if let Some(dir) = dirs::data_dir() {
        return dir.join(APP_DIR_NAME);
    }

    // Legacy fallback
    dirs::home_dir()
        .unwrap_or_else(|| PathBuf::from("~"))
        .join(".bivvy")
}

/// Path to the user's global config file.
///
/// `<config_dir>/config.yml`
pub fn user_config_file() -> PathBuf {
    config_dir().join("config.yml")
}

/// Path to user-level templates directory.
///
/// `<data_dir>/templates`
pub fn user_templates_dir() -> PathBuf {
    data_dir().join("templates")
}

/// Path to the projects state directory.
///
/// `<data_dir>/projects`
pub fn projects_dir() -> PathBuf {
    data_dir().join("projects")
}

/// Path to the project index file.
///
/// `<data_dir>/projects/index.yml`
pub fn project_index_file() -> PathBuf {
    projects_dir().join("index.yml")
}

/// Path to failure reports directory.
///
/// `<data_dir>/failure-reports`
pub fn failure_reports_dir() -> PathBuf {
    data_dir().join("failure-reports")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn config_dir_respects_env_override() {
        let _guard = EnvGuard::new("BIVVY_CONFIG_DIR", "/tmp/test-bivvy-config");
        assert_eq!(config_dir(), PathBuf::from("/tmp/test-bivvy-config"));
    }

    #[test]
    fn data_dir_respects_env_override() {
        let _guard = EnvGuard::new("BIVVY_DATA_DIR", "/tmp/test-bivvy-data");
        assert_eq!(data_dir(), PathBuf::from("/tmp/test-bivvy-data"));
    }

    #[test]
    fn user_config_file_ends_with_config_yml() {
        let _guard = EnvGuard::new("BIVVY_CONFIG_DIR", "/tmp/test-cfg");
        assert_eq!(user_config_file(), PathBuf::from("/tmp/test-cfg/config.yml"));
    }

    #[test]
    fn user_templates_dir_under_data() {
        let _guard = EnvGuard::new("BIVVY_DATA_DIR", "/tmp/test-data");
        assert_eq!(
            user_templates_dir(),
            PathBuf::from("/tmp/test-data/templates")
        );
    }

    #[test]
    fn projects_dir_under_data() {
        let _guard = EnvGuard::new("BIVVY_DATA_DIR", "/tmp/test-data");
        assert_eq!(projects_dir(), PathBuf::from("/tmp/test-data/projects"));
    }

    #[test]
    fn project_index_file_under_projects() {
        let _guard = EnvGuard::new("BIVVY_DATA_DIR", "/tmp/test-data");
        assert_eq!(
            project_index_file(),
            PathBuf::from("/tmp/test-data/projects/index.yml")
        );
    }

    #[test]
    fn failure_reports_dir_under_data() {
        let _guard = EnvGuard::new("BIVVY_DATA_DIR", "/tmp/test-data");
        assert_eq!(
            failure_reports_dir(),
            PathBuf::from("/tmp/test-data/failure-reports")
        );
    }

    #[test]
    fn defaults_use_platform_dirs_when_env_unset() {
        let _guard1 = EnvGuard::clear("BIVVY_CONFIG_DIR");
        let _guard2 = EnvGuard::clear("BIVVY_DATA_DIR");

        // Should not panic and should contain "bivvy" somewhere in the path
        let cfg = config_dir();
        let data = data_dir();
        assert!(cfg.to_string_lossy().contains("bivvy"));
        assert!(data.to_string_lossy().contains("bivvy"));
    }

    /// RAII guard that sets/restores an environment variable for a test.
    struct EnvGuard {
        key: &'static str,
        original: Option<String>,
    }

    impl EnvGuard {
        fn new(key: &'static str, value: &str) -> Self {
            let original = std::env::var(key).ok();
            std::env::set_var(key, value);
            Self { key, original }
        }

        fn clear(key: &'static str) -> Self {
            let original = std::env::var(key).ok();
            std::env::remove_var(key);
            Self { key, original }
        }
    }

    impl Drop for EnvGuard {
        fn drop(&mut self) {
            match &self.original {
                Some(val) => std::env::set_var(self.key, val),
                None => std::env::remove_var(self.key),
            }
        }
    }
}

